import { initialSwStatus, stepSw, type SwEvent, type SwStatus } from '../core/swStatus';

let nextWorkerId = 1;

// Registers the service worker generated by vite-plugin-pwa (sw.js). Updates
// are silent: the new worker activates on this launch and the next launch runs
// the new build (plan section 9, FR-003). In dev there is no sw.js, so skip.
// Every lifecycle event goes through the pure reducer (core/swStatus); `onStatus` gets each new status
// and never throws into the caller (a failing listener must not break the game).
export const registerServiceWorker = (onStatus: (status: SwStatus) => void): void => {
    let status = initialSwStatus;
    const emit = (event: SwEvent): void => {
        status = stepSw(status, event);
        try {
            onStatus(status);
        } catch (error: unknown) {
            // the signal is advisory only
            console.warn(`Service worker status listener failed (${error instanceof Error ? error.name : 'Error'})`);
        }
    };
    if (import.meta.env.DEV || !('serviceWorker' in navigator)) {
        emit({ type: 'unsupported' });
        return;
    }
    const container = navigator.serviceWorker;
    const hadController = container.controller !== null;
    const ids = new WeakMap<ServiceWorker, number>();
    const idOf = (worker: ServiceWorker): number => {
        let id = ids.get(worker);
        if (id === undefined) {
            id = nextWorkerId++;
            ids.set(worker, id);
        }
        return id;
    };
    const track = (worker: ServiceWorker): void => {
        const id = idOf(worker);
        emit({ type: 'installing', id });
        trackStates(worker, id);
    };
    const trackStates = (worker: ServiceWorker, id: number): void => {
        worker.addEventListener('statechange', () => {
            if (worker.state === 'installed' || worker.state === 'activating' || worker.state === 'activated' || worker.state === 'redundant') {
                emit({ type: 'state', id, state: worker.state });
            }
        });
    };
    container.addEventListener('controllerchange', () => emit({ type: 'controllerChange' }));
    emit({ type: 'register', hadController });
    window.addEventListener('load', () => {
        // A failed registration must never break the game; it only means
        // "online only" until the next launch.
        container
            .register('/sw.js', { scope: '/' })
            .then((registration) => {
                if (registration.active) emit({ type: 'active', id: idOf(registration.active) });
                if (registration.waiting) {
                    const id = idOf(registration.waiting);
                    emit({ type: 'waiting', id });
                    trackStates(registration.waiting, id);
                }
                if (registration.installing) track(registration.installing);
                // One update check per launch, nowhere else (autonomous decision 2: no visibility or timer trigger,
                // so a new worker never claims a page in the middle of a round).
                registration.update().catch((error: unknown) => {
                    console.warn(`Service worker update check failed (${error instanceof Error ? error.name : 'Error'})`);
                });
                registration.addEventListener('updatefound', () => {
                    if (registration.installing) track(registration.installing);
                });
            })
            .catch((error: unknown) => {
                const name = error instanceof Error ? error.name : 'Error';
                console.warn(`Service worker registration failed (${name})`);
                emit({ type: 'registerFailed', error: name });
            });
    });
};
